	isAbs, err := p.IsAbsURL(in)
	if err != nil {
		return in
	}
	baseURL := p.getBaseURLRoot(in)
	canonifyURLs := p.Cfg.CanonifyURLs()

	if (!strings.HasPrefix(in, baseURL) && isAbs) || strings.HasPrefix(in, "//") {
