	c.Assert("/index.html", qt.Equals, PrettifyURLPath("/index.html"))
	c.Assert("/name/index.xml", qt.Equals, PrettifyURLPath("/name.xml"))
	c.Assert("/", qt.Equals, PrettifyURLPath("/"))
