func PathEscape(pth string) string {
	// These characters are valid in file paths, but net/url treats them as
	// the start of a query or fragment when parsing a URL. Escape them before
	// parsing so they end up as part of the path.
	pth = strings.NewReplacer("#", "%23", "?", "%3F").Replace(pth)
	u, err := url.Parse(pth)
	if err != nil {
		panic(err)
	}
	return u.EscapedPath()
}

